# ---------- HTML parsing ----------
VOID_ELEMENTS = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr','command','keygen','menuitem'}

RAW_ELEMENTS = {'script','style'}

class Node:
    def __init__(self, typ, tag=None, attrs=None, text=None, is_new=False):
        self.typ = typ  # 'element','text','comment','doctype','document'
        self.tag = tag  # lowercased for element
        self.attrs = attrs if attrs is not None else []  # list of (name, value) where value is str or None for boolean; name lowercased
        self.text = text  # for text/comment/doctype
        self.children = []
        self.parent = None
        self.is_new = is_new  # True for elements created by monolith (serialize with closing)
        self.is_void_original = False  # for original void elements (serialize without closing)
    def append(self, child):
        child.parent = self
        self.children.append(child)

def parse_attrs(s):
    # s is string inside tag after tag name, e.g., ' href="x" disabled'
    attrs = []
    i=0
    n=len(s)
    while i<n:
        # skip whitespace
        while i<n and s[i] in ' \t\n\r\f':
            i+=1
        if i>=n:
            break
        if s[i]=='/':
            # trailing slash for self-closing, ignore?
            i+=1
            continue
        # parse name
        start=i
        while i<n and s[i] not in ' \t\n\r\f=/>':
            i+=1
        name = s[start:i].lower()
        if name=="":
            i+=1
            continue
        # skip ws
        while i<n and s[i] in ' \t\n\r\f':
            i+=1
        if i<n and s[i]=='=':
            i+=1
            while i<n and s[i] in ' \t\n\r\f':
                i+=1
            if i>=n:
                attrs.append((name, ""))
                break
            if s[i] in ('"',"'"):
                q=s[i]
                i+=1
                startv=i
                # find closing quote
                # HTML allows no closing? Take until quote or end
                end = s.find(q, startv)
                if end==-1:
                    val = s[startv:]
                    i=n
                else:
                    val = s[startv:end]
                    i=end+1
                # decode entities in value?
                val = htmlmod.unescape(val)
                attrs.append((name, val))
            else:
                startv=i
                while i<n and s[i] not in ' \t\n\r\f>':
                    i+=1
                val = s[startv:i]
                val = htmlmod.unescape(val)
                attrs.append((name, val))
        else:
            # boolean
            attrs.append((name, None))
    return attrs

def tokenize(html_str):
    # returns list of tokens: ('doctype', text), ('comment', text), ('start', tag, attrs, selfclosing), ('end', tag), ('text', text)
    tokens=[]
    pos=0
    L=len(html_str)
    while pos<L:
        if html_str.startswith('<!--', pos):
            end = html_str.find('-->', pos+4)
            if end==-1:
                tokens.append(('comment', html_str[pos+4:]))
                break
            else:
                tokens.append(('comment', html_str[pos+4:end]))
                pos=end+3
                continue
        elif html_str.startswith('<!', pos):
            # doctype or other decl like <!DOCTYPE...>
            end = html_str.find('>', pos+2)
            if end==-1:
                tokens.append(('text', html_str[pos:]))
                break
            else:
                decl = html_str[pos:end+1]
                # check if doctype (case-insensitive)
                if decl[2:].lstrip().lower().startswith('doctype'):
                    tokens.append(('doctype', decl))
                else:
                    # bogus comment? treat as comment? For simplicity, treat as comment?
                    # Actually <!...> unknown -> treat as comment? We'll treat as text?
                    tokens.append(('comment', decl[2:-1] if decl.endswith('>') else decl[2:]))
                pos=end+1
                continue
        elif html_str[pos]=='<':
            # tag?
            # find >
            # need to handle quotes inside?
            # Find next > not inside quotes
            i=pos+1
            in_q=None
            while i<L:
                c=html_str[i]
                if in_q:
                    if c==in_q:
                        in_q=None
                else:
                    if c in ('"',"'"):
                        in_q=c
                    elif c=='>':
                        break
                i+=1
            if i>=L:
                tokens.append(('text', html_str[pos:]))
                break
            tagtext = html_str[pos:i+1]
            pos=i+1
            # parse tagtext
            inner = tagtext[1:-1].strip()
            if inner.startswith('/'):
                # end tag
                name = inner[1:].strip().split()[0].lower() if inner[1:].strip() else ""
                # remove trailing slash? not needed
                tokens.append(('end', name))
            else:
                # start tag (maybe self-closing)
                selfclosing = False
                if inner.endswith('/'):
                    selfclosing=True
                    inner=inner[:-1].strip()
                # split tag name and attrs
                parts = inner.split(None,1)
                if not parts:
                    continue
                tag = parts[0].lower()
                attrstr = parts[1] if len(parts)>1 else ""
                attrs = parse_attrs(attrstr)
                tokens.append(('start', tag, attrs, selfclosing))
            continue
        else:
            # text until next <
            nxt = html_str.find('<', pos)
            if nxt==-1:
                tokens.append(('text', html_str[pos:]))
                break
            else:
                # check if < is start of tag or just text? For script/style raw? Handled later?
                # For now, treat as text
                tokens.append(('text', html_str[pos:nxt]))
                pos=nxt
                continue
    return tokens

