def escape_text(s):
    # text node escaping: & -> &amp;, < -> &lt;, > -> &gt;, \xa0 -> &nbsp;
    # Order: & first, then <, >, then \xa0? But & in &nbsp;? No, \xa0 is char, not entity.
    # Must be careful: s is decoded (e.g., "&" char). So replace & first.
    s = s.replace('&', '&amp;')
    s = s.replace('<', '&lt;')
    s = s.replace('>', '&gt;')
    s = s.replace('\xa0', '&nbsp;')
    return s

def escape_attr(s):
    s = s.replace('&', '&amp;')
    s = s.replace('"', '&quot;')
    s = s.replace('\xa0', '&nbsp;')
    return s

def serialize_node(node):
    if node.typ == 'document':
        return ''.join(serialize_node(c) for c in node.children)
    elif node.typ == 'doctype':
        return node.text
    elif node.typ == 'comment':
        return f'<!--{node.text}-->'
    elif node.typ == 'text':
        if getattr(node, 'is_raw_text', False):
            return node.text
        else:
            return escape_text(node.text)
    elif node.typ == 'element':
        tag = node.tag
        # attrs
        attr_str = ""
        for k,v in node.attrs:
            if v is None:
                # boolean: serialize as attr="" ? Observed async="" etc.
                # For boolean, output attr="" (with empty value)
                attr_str += f' {k}=""'
            else:
                attr_str += f' {k}="{escape_attr(v)}"'
        if tag in VOID_ELEMENTS:
            if node.is_new:
                return f'<{tag}{attr_str}></{tag}>'
            else:
                return f'<{tag}{attr_str}>'
        else:
            # raw? script/style content is text nodes with is_raw_text True, already handled
            inner = ''.join(serialize_node(c) for c in node.children)
            return f'<{tag}{attr_str}>{inner}</{tag}>'
    return ""

def find_head_body(doc):
    # doc is document with html child
    html_node = None
    for c in doc.children:
        if c.typ == 'element' and c.tag == 'html':
            html_node = c
            break
    if html_node is None:
        return None, None, None
    head = None
    body = None
    frameset = None
    for c in html_node.children:
        if c.typ == 'element' and c.tag == 'head' and head is None:
            head = c
        elif c.typ == 'element' and c.tag == 'body' and body is None:
            body = c
        elif c.typ == 'element' and c.tag == 'frameset' and frameset is None:
            frameset = c
    return html_node, head, body if body is not None else frameset

def get_attr(elem, name):
    for k,v in elem.attrs:
        if k == name:
            return v
    return None

def set_attr(elem, name, value):
    for i,(k,v) in enumerate(elem.attrs):
        if k == name:
            elem.attrs[i] = (k, value)
            return
    elem.attrs.append((name, value))

def remove_attr(elem, name):
    elem.attrs = [(k,v) for k,v in elem.attrs if k != name]

def has_attr(elem, name):
    return any(k==name for k,v in elem.attrs)

